INSERT INTO fx_triggers (id, takes, built, origin, note) VALUES
('skill_hit', '', 1, 'chance to gain a Power Charge on Critical Strike', 'A skill the actor used itself hit an enemy: once per enemy hit, as the charge rules count hits. It carries what the hit found: critical or not, spell or attack, melee, whether it killed, the enemy''s rarity and state (frozen, bleeding, marked) and the actor''s own (bleeding, poisoned). The trigger "hit" is every hit of the actor''s side, its totems, traps and mines included.')
INSERT INTO fx_conditions (id, takes, built, origin, note) VALUES
('self_state', 'is: bleeding, poisoned', 1, 'gain a Power Charge on Hit while Bleeding', 'The actor itself is in that state at the trigger.')
