-- The charge rules of ChargeGains.cs as fx rules, one per stat: the same event, the same conditions, the same
-- chance (the stat's value; the hitting or killing skill adds what it has of the stat itself: "skill": true) and the same
-- outcome (gain one, gain up to the maximum, lose all, lose one; a random type where the code drew one). While a
-- rule is live for a character (it has the stat), ChargeGains leaves the stat to it; for a character without the
-- stat the code still rolls a skill's own share. With the rules off the code does everything, as before.
-- Not here: the four rules of one skill each (Sweep, Ice Spear, Power Siphon, Frenzy) and the charges gained over time.
ON CONFLICT(id) DO NOTHING;
ON CONFLICT(id) DO NOTHING;
UPDATE fx_conditions SET takes = 'is: frozen, ignited, bleeding, poisoned, five_poisons (5 or more poisons on it), marked, killed' WHERE id = 'enemy_state';
UPDATE fx_conditions SET takes = takes || '. In a rule: shield, dual wielding, wand, claw or dagger' WHERE id = 'weapon';
UPDATE fx_actions SET takes = 'type: endurance, frenzy, power, random; does: gain (the default), to_maximum, lose_all, lose_one; the value is how many to gain', note = 'Gives the target charges, or takes them: through the charge rules, with the maximum and the refresh they give any gain.' WHERE id = 'charge';
UPDATE fx_values SET takes = 'skill: true to add what the trigger''s own skill has of the same stat (a support''s chance with the character''s)' WHERE id = 'roll';
ON CONFLICT(stat) DO UPDATE SET kind = 'trigger', handled = 'rule', ref = excluded.ref;
